/* ===== Reset & Base ===== */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  font-size: 13px;
  color: #1a1a1a;
  user-select: none;
  -webkit-user-select: none;
}

/* ===== Desktop ===== */
#desktop {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 48px;
  overflow: hidden;
  /* Default wallpaper: a nice gradient */
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
}

/* Wallpaper presets */
#desktop.wallpaper-0 { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); }
#desktop.wallpaper-1 { background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%); }
#desktop.wallpaper-2 { background: linear-gradient(135deg, #4facfe 0%, #00f2fe 100%); }
#desktop.wallpaper-3 { background: linear-gradient(135deg, #43e97b 0%, #38f9d7 100%); }
#desktop.wallpaper-4 { background: linear-gradient(135deg, #fa709a 0%, #fee140 100%); }
#desktop.wallpaper-5 { background: linear-gradient(135deg, #a18cd1 0%, #fbc2eb 100%); }
#desktop.wallpaper-6 { background-color: #1a1a2e; }
#desktop.wallpaper-7 {
  background-color: #0f0f23;
  background-image:
    radial-gradient(ellipse at 20% 50%, rgba(72, 52, 212, 0.3) 0%, transparent 50%),
    radial-gradient(ellipse at 80% 50%, rgba(120, 40, 200, 0.2) 0%, transparent 50%);
}

/* ===== Desktop Icons ===== */
#desktop-icons {
  position: absolute;
  top: 16px;
  left: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  z-index: 1;
}

.desktop-icon {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 80px;
  padding: 8px 4px;
  border-radius: 8px;
  cursor: default;
  transition: background 0.15s;
}

.desktop-icon:hover {
  background: rgba(255, 255, 255, 0.15);
}

.desktop-icon:active {
  background: rgba(255, 255, 255, 0.25);
}

.desktop-icon-svg {
  width: 40px;
  height: 40px;
  margin-bottom: 4px;
  pointer-events: none;
}

.desktop-icon-label {
  color: white;
  font-size: 11px;
  text-align: center;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.6);
  line-height: 1.2;
  pointer-events: none;
  word-break: break-word;
}

/* ===== Windows ===== */
.window {
  position: absolute;
  min-width: 300px;
  min-height: 200px;
  border-radius: 10px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.25), 0 2px 8px rgba(0, 0, 0, 0.1);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transition: box-shadow 0.2s;
}

.window.focused {
  box-shadow: 0 12px 48px rgba(0, 0, 0, 0.3), 0 4px 12px rgba(0, 0, 0, 0.15);
}

.window:not(.focused) {
  opacity: 0.95;
}

/* Title bar */
.window-titlebar {
  display: flex;
  align-items: center;
  height: 36px;
  padding: 0 8px;
  background: #f3f3f3;
  border-bottom: 1px solid #e0e0e0;
  flex-shrink: 0;
  cursor: default;
}

.window.focused .window-titlebar {
  background: #ffffff;
  border-bottom-color: #d0d0d0;
}

.window-titlebar-text {
  flex: 1;
  font-size: 12px;
  font-weight: 500;
  color: #333;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  pointer-events: none;
}

.window-close-btn {
  width: 28px;
  height: 28px;
  border: none;
  background: transparent;
  border-radius: 6px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #666;
  font-size: 16px;
  transition: background 0.15s, color 0.15s;
}

.window-close-btn:hover {
  background: #e8e8e8;
  color: #333;
}

.window.focused .window-close-btn:hover {
  background: #e53935;
  color: white;
}

/* Window body */
.window-body {
  flex: 1;
  overflow: auto;
  background: #ffffff;
  position: relative;
}

/* Window placeholder content */
.window-body .placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  color: #999;
  font-size: 14px;
}

/* Resize handle */
.window-resize-handle {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 16px;
  height: 16px;
  cursor: nwse-resize;
  z-index: 10;
}

/* ===== Taskbar ===== */
#taskbar {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  height: 48px;
  background: rgba(243, 243, 243, 0.85);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-top: 1px solid rgba(0, 0, 0, 0.08);
  display: flex;
  align-items: center;
  padding: 0 8px;
  z-index: 10000;
}

#taskbar-buttons {
  flex: 1;
  display: flex;
  gap: 4px;
  overflow-x: auto;
  align-items: center;
}

.taskbar-button {
  height: 36px;
  padding: 0 14px;
  border: none;
  background: transparent;
  border-radius: 6px;
  cursor: pointer;
  font-size: 12px;
  font-family: inherit;
  color: #333;
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: background 0.15s;
  position: relative;
}

.taskbar-button:hover {
  background: rgba(0, 0, 0, 0.06);
}

.taskbar-button.active {
  background: rgba(0, 0, 0, 0.1);
}

.taskbar-button.active::after {
  content: '';
  position: absolute;
  bottom: 2px;
  left: 50%;
  transform: translateX(-50%);
  width: 18px;
  height: 3px;
  border-radius: 2px;
  background: #0078d4;
}

.taskbar-clock {
  padding: 0 12px;
  font-size: 12px;
  color: #333;
  white-space: nowrap;
  min-width: 60px;
  text-align: right;
}

/* ===== Context Menu ===== */
.context-menu {
  position: fixed;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-radius: 8px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.18);
  border: 1px solid rgba(0, 0, 0, 0.08);
  padding: 4px;
  z-index: 20000;
  min-width: 180px;
}

.context-menu.hidden {
  display: none;
}

.context-menu-item {
  padding: 8px 16px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 12px;
  color: #333;
  transition: background 0.1s;
}

.context-menu-item:hover {
  background: rgba(0, 120, 212, 0.1);
}

/* ===== Scrollbar styling ===== */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: transparent;
}

::-webkit-scrollbar-thumb {
  background: rgba(0, 0, 0, 0.15);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: rgba(0, 0, 0, 0.25);
}

/**
 * Browser OS — script.js
 * 
 * Ticket 1: Desktop shell — Window manager and taskbar.
 * 
 * Architecture:
 * - WindowRegistry: manages all open windows, z-order, focus.
 * - Taskbar: renders buttons for each open window, shows clock.
 * - Desktop icons: double-click to open app windows.
 * - Drag and resize for windows.
 */

(function () {
  'use strict';

  // ===== Configuration =====
  const WINDOW_START_X = 60;
  const WINDOW_START_Y = 40;
  const WINDOW_SPACING = 24;
  const MIN_WINDOW_WIDTH = 300;
  const MIN_WINDOW_HEIGHT = 200;
  const TASKBAR_HEIGHT = 48;

  // ===== Global state =====
  let currentZIndex = 100;
  let nextWindowOffset = 0;

  // ===== Window Registry =====
  const WindowRegistry = {
    /** @type {Map<string, WindowRecord>} */
    windows: new Map(),

    /**
     * @typedef {Object} WindowRecord
     * @property {string} appId
     * @property {string} title
     * @property {HTMLElement} element
     * @property {number} x
     * @property {number} y
     * @property {number} width
     * @property {number} height
     * @property {boolean} maximized
     */

    /**
     * Register a new window.
     * @param {string} appId - Unique app identifier
     * @param {string} title - Window title
     * @param {number} width - Window width
     * @param {number} height - Window height
     * @param {Function} renderBody - Function to render the window body content
     * @returns {WindowRecord}
     */
    register(appId, title, width, height, renderBody) {
      // Single instance per app: if already open, focus and return
      if (this.windows.has(appId)) {
        const existing = this.windows.get(appId);
        this.focus(appId);
        return existing;
      }

      const { x, y } = this._getNextPosition(width, height);

      const el = this._createWindowElement(appId, title, x, y, width, height);
      if (renderBody) {
        renderBody(el.querySelector('.window-body'));
      }

      document.getElementById('windows-container').appendChild(el);

      const record = {
        appId,
        title,
        element: el,
        x,
        y,
        width,
        height,
        maximized: false
      };

      this.windows.set(appId, record);
      this.focus(appId);
      Taskbar.sync();
      return record;
    },

    /**
     * @param {string} appId
     */
    close(appId) {
      const record = this.windows.get(appId);
      if (!record) return;

      record.element.remove();
      this.windows.delete(appId);
      Taskbar.sync();
    },

    /**
     * @param {string} appId
     */
    focus(appId) {
      const record = this.windows.get(appId);
      if (!record) return;

      // De-focus all windows
      this.windows.forEach((rec) => {
        rec.element.classList.remove('focused');
        rec.element.style.zIndex = parseInt(rec.element.style.zIndex, 10) || 100;
      });

      // Focus this window
      currentZIndex++;
      record.element.style.zIndex = currentZIndex;
      record.element.classList.add('focused');

      // Update taskbar
      Taskbar.sync();
    },

    /**
     * @param {string} appId
     */
    isFocused(appId) {
      const record = this.windows.get(appId);
      if (!record) return false;
      return record.element.classList.contains('focused');
    },

    /**
     * @param {string} appId
     */
    exists(appId) {
      return this.windows.has(appId);
    },

    /**
     * @param {number} width
     * @param {number} height
     * @returns {{x: number, y: number}}
     */
    _getNextPosition(width, height) {
      const desktopEl = document.getElementById('desktop');
      const desktopW = desktopEl.clientWidth;
      const desktopH = desktopEl.clientHeight;

      // Stagger windows
      const ox = (nextWindowOffset % 8) * WINDOW_SPACING;
      const oy = (nextWindowOffset % 8) * WINDOW_SPACING;
      nextWindowOffset++;

      let x = WINDOW_START_X + ox;
      let y = WINDOW_START_Y + oy;

      // Constrain to viewport
      if (x + width > desktopW - 10) x = Math.max(10, desktopW - width - 10);
      if (y + height > desktopH - 10) y = Math.max(10, desktopH - height - 10);
      if (x < 10) x = 10;
      if (y < 10) y = 10;

      return { x, y };
    },

    /**
     * @param {string} appId
     * @param {string} title
     * @param {number} x
     * @param {number} y
     * @param {number} width
     * @param {number} height
     * @returns {HTMLElement}
     */
    _createWindowElement(appId, title, x, y, width, height) {
      const el = document.createElement('div');
      el.className = 'window focused';
      el.dataset.appId = appId;
      el.style.left = x + 'px';
      el.style.top = y + 'px';
      el.style.width = width + 'px';
      el.style.height = height + 'px';
      el.style.zIndex = ++currentZIndex;

      // Title bar
      const titlebar = document.createElement('div');
      titlebar.className = 'window-titlebar';

      const titleText = document.createElement('span');
      titleText.className = 'window-titlebar-text';
      titleText.textContent = title;

      const closeBtn = document.createElement('button');
      closeBtn.className = 'window-close-btn';
      closeBtn.innerHTML = '&#x2715;';
      closeBtn.title = 'Close';
      closeBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        this.close(appId);
      });

      titlebar.appendChild(titleText);
      titlebar.appendChild(closeBtn);

      // Window body
      const body = document.createElement('div');
      body.className = 'window-body';

      // Resize handle
      const resizeHandle = document.createElement('div');
      resizeHandle.className = 'window-resize-handle';

      el.appendChild(titlebar);
      el.appendChild(body);
      el.appendChild(resizeHandle);

      // --- Drag logic ---
      let isDragging = false;
      let dragStartX = 0;
      let dragStartY = 0;
      let winStartX = 0;
      let winStartY = 0;

      titlebar.addEventListener('mousedown', (e) => {
        if (e.target.classList.contains('window-close-btn')) return;
        e.preventDefault();
        isDragging = true;
        this.focus(appId);

        dragStartX = e.clientX;
        dragStartY = e.clientY;
        winStartX = parseInt(el.style.left, 10);
        winStartY = parseInt(el.style.top, 10);

        const onMove = (ev) => {
          if (!isDragging) return;
          let newX = winStartX + (ev.clientX - dragStartX);
          let newY = winStartY + (ev.clientY - dragStartY);

          // Constrain to viewport
          const desktopEl = document.getElementById('desktop');
          const desktopH = desktopEl.clientHeight;
          const maxTop = desktopH - height;
          if (newY > maxTop) newY = maxTop;
          if (newY < 0) newY = 0;
          if (newX < 0) newX = 0;
          const maxX = desktopEl.clientWidth - width;
          if (newX > maxX) newX = maxX;

          el.style.left = newX + 'px';
          el.style.top = newY + 'px';
          record.x = newX;
          record.y = newY;
        };

        const onUp = () => {
          isDragging = false;
          document.removeEventListener('mousemove', onMove);
          document.removeEventListener('mouseup', onUp);
        };

        document.addEventListener('mousemove', onMove);
        document.addEventListener('mouseup', onUp);
      });

      // --- Resize logic ---
      let isResizing = false;
      let resizeStartX = 0;
      let resizeStartY = 0;
      let resizeStartW = 0;
      let resizeStartH = 0;

      resizeHandle.addEventListener('mousedown', (e) => {
        e.preventDefault();
        e.stopPropagation();
        isResizing = true;
        this.focus(appId);

        resizeStartX = e.clientX;
        resizeStartY = e.clientY;
        resizeStartW = width;
        resizeStartH = height;

        const onMove = (ev) => {
          if (!isResizing) return;
          let newW = Math.max(MIN_WINDOW_WIDTH, resizeStartW + (ev.clientX - resizeStartX));
          let newH = Math.max(MIN_WINDOW_HEIGHT, resizeStartH + (ev.clientY - resizeStartY));

          el.style.width = newW + 'px';
          el.style.height = newH + 'px';
          record.width = newW;
          record.height = newH;
        };

        const onUp = () => {
          isResizing = false;
          document.removeEventListener('mousemove', onMove);
          document.removeEventListener('mouseup', onUp);
        };

        document.addEventListener('mousemove', onMove);
        document.addEventListener('mouseup', onUp);
      });

      // --- Focus on click ---
      el.addEventListener('mousedown', () => {
        this.focus(appId);
      });

      return el;
    }
  };

  // ===== Taskbar =====
  const Taskbar = {
    /**
     * Rebuild the taskbar button list to match the window registry.
     */
    sync() {
      const container = document.getElementById('taskbar-buttons');
      container.innerHTML = '';

      WindowRegistry.windows.forEach((record) => {
        const btn = document.createElement('button');
        btn.className = 'taskbar-button' + (WindowRegistry.isFocused(record.appId) ? ' active' : '');
        btn.textContent = record.title;

        btn.addEventListener('click', () => {
          if (WindowRegistry.isFocused(record.appId)) {
            // Minimize: unfocus / hide — for simplicity we just minimize
            WindowRegistry.close(record.appId);
          } else {
            WindowRegistry.focus(record.appId);
          }
        });

        container.appendChild(btn);
      });

      Taskbar.updateClock();
    },

    /**
     * Update the clock display.
     */
    updateClock() {
      const clockEl = document.getElementById('taskbar-clock');
      const now = new Date();
      const hours = String(now.getHours()).padStart(2, '0');
      const minutes = String(now.getMinutes()).padStart(2, '0');
      clockEl.textContent = hours + ':' + minutes;
    }
  };

  // ===== Desktop =====
  const Desktop = {
    init() {
      // Double-click handler for desktop icons
      document.querySelectorAll('.desktop-icon').forEach((icon) => {
        let clickCount = 0;
        let clickTimer = null;

        icon.addEventListener('click', () => {
          clickCount++;
          if (clickCount === 1) {
            clickTimer = setTimeout(() => {
              clickCount = 0;
            }, 300);
          } else if (clickCount === 2) {
            clearTimeout(clickTimer);
            clickCount = 0;
            const appId = icon.dataset.app;
            Desktop.openApp(appId);
          }
        });
      });

      // Context menu on desktop background
      document.getElementById('desktop').addEventListener('contextmenu', (e) => {
        // Only show on empty desktop area (not on icons or windows)
        if (e.target.closest('.desktop-icon') || e.target.closest('.window')) return;
        e.preventDefault();
        Desktop.showContextMenu(e.clientX, e.clientY);
      });

      // Close context menu on click elsewhere
      document.addEventListener('click', (e) => {
        if (!e.target.closest('.context-menu')) {
          Desktop.hideContextMenu();
        }
      });

      // Clock updates every minute
      setInterval(() => Taskbar.updateClock(), 10000);
      Taskbar.updateClock();

      // Initial clock update
      setTimeout(() => Taskbar.updateClock(), 100);
    },

    /**
     * @param {string} appId
     */
    openApp(appId) {
      switch (appId) {
        case 'notepad':
          this._openNotepad();
          break;
        case 'calculator':
          this._openCalculator();
          break;
        case 'minesweeper':
          this._openMinesweeper();
          break;
        case 'spider':
          this._openSpider();
          break;
      }
    },

    /**
     * @param {number} x
     * @param {number} y
     */
    showContextMenu(x, y) {
      const menu = document.getElementById('context-menu');
      const content = document.getElementById('context-menu-content');
      content.innerHTML = '';

      const item = document.createElement('div');
      item.className = 'context-menu-item';
      item.textContent = 'Change wallpaper…';
      item.addEventListener('click', () => {
        Desktop.hideContextMenu();
        Desktop.showWallpaperPicker();
      });
      content.appendChild(item);

      menu.style.left = x + 'px';
      menu.style.top = y + 'px';
      menu.classList.remove('hidden');

      // Adjust if off-screen
      const rect = menu.getBoundingClientRect();
      if (rect.right > window.innerWidth) {
        menu.style.left = (x - rect.width) + 'px';
      }
      if (rect.bottom > window.innerHeight - TASKBAR_HEIGHT) {
        menu.style.top = (y - rect.height) + 'px';
      }
    },

    hideContextMenu() {
      document.getElementById('context-menu').classList.add('hidden');
    },

    showWallpaperPicker() {
      // Placeholder for wallpaper picker (ticket 2)
      // For now, show a simple context menu with preset options
      const menu = document.getElementById('context-menu');
      const content = document.getElementById('context-menu-content');
      content.innerHTML = '';

      for (let i = 0; i < 8; i++) {
        const item = document.createElement('div');
        item.className = 'context-menu-item';
        item.textContent = 'Preset ' + (i + 1);
        item.addEventListener('click', () => {
          Desktop.setWallpaper(i);
          Desktop.hideContextMenu();
        });
        content.appendChild(item);
      }

      menu.style.left = '10px';
      menu.style.top = '10px';
      menu.classList.remove('hidden');
    },

    /**
     * @param {number} index
     */
    setWallpaper(index) {
      const desktop = document.getElementById('desktop');
      desktop.className = '';
      desktop.classList.add('wallpaper-' + index);
      // Persist in localStorage (ticket 6)
      try {
        localStorage.setItem('browser-os-wallpaper', String(index));
      } catch (e) { /* ignore */ }
    }
  };

  // ===== App Launchers (placeholder content for ticket 1) =====

  Desktop._openNotepad = function () {
    WindowRegistry.register('notepad', 'Notepad — Untitled', 550, 400, (body) => {
      body.innerHTML = '<div class="placeholder">Notepad — Double-click the desktop icon to open. Full implementation in a later ticket.</div>';
    });
  };

  Desktop._openCalculator = function () {
    WindowRegistry.register('calculator', 'Calculator', 320, 440, (body) => {
      body.innerHTML = '<div class="placeholder">Calculator — Full implementation in a later ticket.</div>';
    });
  };

  Desktop._openMinesweeper = function () {
    WindowRegistry.register('minesweeper', 'Minesweeper', 400, 450, (body) => {
      body.innerHTML = '<div class="placeholder">Minesweeper — Full implementation in a later ticket.</div>';
    });
  };

  Desktop._openSpider = function () {
    WindowRegistry.register('spider', 'Spider Solitaire', 800, 560, (body) => {
      body.innerHTML = '<div class="placeholder">Spider Solitaire — Full implementation in a later ticket.</div>';
    });
  };

  // ===== Initialize =====
  document.addEventListener('DOMContentLoaded', () => {
    Desktop.init();

    // Restore wallpaper from localStorage
    try {
      const saved = localStorage.getItem('browser-os-wallpaper');
      if (saved !== null) {
        Desktop.setWallpaper(parseInt(saved, 10) || 0);
      }
    } catch (e) { /* ignore */ }
  });

  // Expose for testing
  window.WindowRegistry = WindowRegistry;
  window.Taskbar = Taskbar;
  window.Desktop = Desktop;
})();

