  const icon = icons[0];
  icon.dispatchEvent(new MouseEvent("click",{bubbles:true}));
  icon.dispatchEvent(new MouseEvent("click",{bubbles:true}));
  const windows1 = document.querySelectorAll(".window");
  results.push({ test: "Double-click opens window", pass: windows1.length === 1 });

  // 3. Window has correct structure
  const w = windows1[0];
  const hasTitlebar = !!w.querySelector(".window-titlebar");
  const hasCloseBtn = !!w.querySelector(".window-close-btn");
  const hasBody = !!w.querySelector(".window-body");
  const hasResizeHandle = !!w.querySelector(".window-resize-handle");
  results.push({ test: "Window has title bar", pass: hasTitlebar });
  results.push({ test: "Window has close button", pass: hasCloseBtn });
  results.push({ test: "Window has body", pass: hasBody });
  results.push({ test: "Window has resize handle", pass: hasResizeHandle });

  // 4. Window is focused
  results.push({ test: "Window is focused on open", pass: w.classList.contains("focused") });

  // 5. Title bar shows app name
  const titleText = w.querySelector(".window-titlebar-text").textContent;
  results.push({ test: "Title bar shows app name", pass: titleText.includes("Notepad") });

  // 6. Single instance per app
  icon.dispatchEvent(new MouseEvent("click",{bubbles:true}));
  icon.dispatchEvent(new MouseEvent("click",{bubbles:true}));
  results.push({ test: "Single instance per app", pass: document.querySelectorAll(".window").length === 1 });

  // 7. Window drag
  const titlebar = w.querySelector(".window-titlebar");
  titlebar.dispatchEvent(new MouseEvent("mousedown",{bubbles:true,clientX:10,clientY:10}));
  document.dispatchEvent(new MouseEvent("mousemove",{bubbles:true,clientX:110,clientY:60}));
  document.dispatchEvent(new MouseEvent("mouseup",{bubbles:true}));
  const newX = parseInt(w.style.left, 10);
  const newY = parseInt(w.style.top, 10);
  results.push({ test: "Window is draggable", pass: newX > 60 && newY > 40 });

  // 8. Window constrained to viewport
  titlebar.dispatchEvent(new MouseEvent("mousedown",{bubbles:true,clientX:0,clientY:0}));
  document.dispatchEvent(new MouseEvent("mousemove",{bubbles:true,clientX:-1000,clientY:-1000}));
  document.dispatchEvent(new MouseEvent("mouseup",{bubbles:true}));
  const constrainedX = parseInt(w.style.left, 10) >= 0;
  const constrainedY = parseInt(w.style.top, 10) >= 0;
  results.push({ test: "Window constrained to viewport (x)", pass: constrainedX });
  results.push({ test: "Window constrained to viewport (y)", pass: constrainedY });

  // 9. Focus switching
  const apps = ["calculator","minesweeper","spider"];
  apps.forEach(app => {
    const ic = document.querySelector(".desktop-icon[data-app=\""+app+"\"]");
    ic.dispatchEvent(new MouseEvent("click",{bubbles:true}));
    ic.dispatchEvent(new MouseEvent("click",{bubbles:true}));
  });
  const allWindows = document.querySelectorAll(".window");
  // Click on calculator body to focus it
  const calcBody = allWindows[1].querySelector(".window-body");
  const calcRect = calcBody.getBoundingClientRect();
  calcBody.dispatchEvent(new MouseEvent("mousedown",{bubbles:true,clientX:calcRect.left+10,clientY:calcRect.top+10}));
  const calcFocused = allWindows[1].classList.contains("focused");
  results.push({ test: "Focus switches on click", pass: calcFocused });

  // 10. Taskbar buttons
  const tbBtns = document.querySelectorAll(".taskbar-button");
  results.push({ test: "Taskbar has buttons for open windows", pass: tbBtns.length === 4 });

  // 11. Active button highlighted
  const activeBtns = Array.from(tbBtns).filter(b => b.classList.contains("active"));
  results.push({ test: "Active taskbar button highlighted", pass: activeBtns.length === 1 });

  // 12. Clock exists
  const clock = document.getElementById("taskbar-clock");
  const hasClock = clock && clock.textContent.length >= 4;
  results.push({ test: "Taskbar clock exists and shows time", pass: hasClock });

  // 13. Close button works
  WindowRegistry.close("notepad");
  results.push({ test: "Close button removes window", pass: document.querySelectorAll(".window").length === 3 });
  results.push({ test: "Taskbar updates on close", pass: document.querySelectorAll(".taskbar-button").length === 3 });

  // 14. Context menu on desktop
  const desktop = document.getElementById("desktop");
  desktop.dispatchEvent(new MouseEvent("contextmenu",{bubbles:true,clientX:50,clientY:50}));
  const ctxMenu = document.getElementById("context-menu");
  results.push({ test: "Context menu appears on right-click", pass: !ctxMenu.classList.contains("hidden") });

  // Summary
  const allPass = results.every(r => r.pass);
  const summary = allPass ? "ALL PASS" : "SOME FAILED";
  return { summary, results };
}'

