/* ===== Calculator ===== */
#calc-window .window-body {
  display: flex;
  flex-direction: column;
  background: #f9f9f9;
  overflow: hidden;
}

.calc-display {
  background: #ffffff;
  border-bottom: 1px solid #e0e0e0;
  padding: 12px 16px;
  text-align: right;
  min-height: 80px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}

.calc-expression {
  font-size: 13px;
  color: #999;
  min-height: 18px;
  margin-bottom: 4px;
  word-break: break-all;
}

.calc-result {
  font-size: 32px;
  font-weight: 300;
  color: #1a1a1a;
  line-height: 1.1;
  word-break: break-all;
}

.calc-buttons {
  flex: 1;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: repeat(5, 1fr);
  gap: 1px;
  background: #e0e0e0;
  padding: 1px;
}

.calc-btn {
  border: none;
  background: #ffffff;
  font-size: 18px;
  font-family: inherit;
  font-weight: 400;
  color: #1a1a1a;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.1s;
  min-height: 52px;
  padding: 4px;
}

.calc-btn:hover {
  background: #f0f0f0;
}

.calc-btn:active {
  background: #e5e5e5;
}

.calc-btn.operator {
  background: #f0f0f0;
  color: #0078d4;
  font-size: 20px;
}

.calc-btn.operator:hover {
  background: #e5e5e5;
}

.calc-btn.operator.active {
  background: #0078d4;
  color: white;
}

.calc-btn.equals {
  background: #0078d4;
  color: white;
  font-size: 22px;
}

.calc-btn.equals:hover {
  background: #006cbd;
}

.calc-btn.equals:active {
  background: #005a9e;
}

.calc-btn.clear {
  background: #f0f0f0;
  color: #e53935;
}

.calc-btn.clear:hover {
  background: #e5e5e5;
}

/* ===== Scrollbar styling ===== */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

