(function() {
    const calc = window.Calculator;
    const win = document.querySelector('.window[data-app-id="calculator"]');
    if (!win) {
        console.log('FAIL: Calculator window not found');
        return;
    }
    const resultEl = win.querySelector('.calc-result');
    const exprEl = win.querySelector('.calc-expression');
    const btns = win.querySelectorAll('.calc-btn');
    let results = [];
    let allPass = true;
    function assert(name, actual, expected) {
        const pass = actual === expected;
        if (!pass) { allPass = false; results.push(name + ': got "' + actual + '", expected "' + expected + '"'); }
        console.log(pass ? 'PASS' : 'FAIL', name, ':', actual, pass ? '' : '(expected ' + expected + ')');
    }

    // Test 1: Initial state
    calc.reset();
    assert('Initial display', resultEl.textContent, '0');
    assert('Initial expression', exprEl.textContent, '');

    // Test 2: Enter digits
    calc.reset();
    btns.forEach(b => b.click());
    calc.reset();
    btns[7].click(); // "5"
    assert('After 5', resultEl.textContent, '5');
    btns[8].click(); // "3"
    assert('After 53', resultEl.textContent, '53');

    // Test 3: Simple addition 2+3=5
    calc.reset();
    btns[10].click(); // "2"
    btns[15].click(); // "+"
    assert('Expression shows 2 +', exprEl.textContent.includes('2'), true);
    btns[11].click(); // "3"
    assert('After entering 3', resultEl.textContent, '3');
    btns[18].click(); // "="
    assert('2+3=5', resultEl.textContent.replace(/,/g, ''), '5');

    // Test 4: Subtraction 10-3=7
    calc.reset();
    btns[6].click(); btns[7].click(); // "10"
    btns[14].click(); // "-"
    btns[11].click(); // "3"
    btns[18].click(); // "="
    assert('10-3=7', resultEl.textContent.replace(/,/g, ''), '7');

    // Test 5: Multiplication 65*4=260
    calc.reset();
    btns[9].click(); btns[10].click(); // "65"
    btns[13].click(); // "*"
    btns[11].click(); // "4"
    btns[18].click(); // "="
    assert('65x4=260', resultEl.textContent.replace(/,/g, ''), '260');

    // Test 6: Division 100/4=25
    calc.reset();
    btns[6].click(); btns[7].click(); btns[8].click(); // "100"
    btns[12].click(); // "/"
    btns[11].click(); // "4"
    btns[18].click(); // "="
    assert('100/4=25', resultEl.textContent.replace(/,/g, ''), '25');

    // Test 7: Thousand separator
    calc.reset();
    btns[6].click(); btns[7].click(); btns[8].click(); // "1000"
    assert('1000 with comma', resultEl.textContent, '1,000');

    // Test 8: Decimal
    calc.reset();
    btns[9].click(); // "3"
    btns[17].click(); // "."
    btns[10].click(); btns[11].click(); // "14"
    assert('3.14', resultEl.textContent, '3.14');

    // Test 9: Double decimal prevented
    calc.reset();
    btns[6].click(); // "1"
    btns[17].click(); // "."
    btns[17].click(); // "." again - should be ignored
    assert('No double decimal', resultEl.textContent, '1.');

    // Test 10: Divide by zero
    calc.reset();
    btns[6].click(); // "1"
    btns[12].click(); // "/"
    btns[7].click(); // "0"
    btns[18].click(); // "="
    assert('Divide by zero = Error', resultEl.textContent, 'Error');

    // Test 11: Error clears on next input
    btns[10].click(); // "2"
    assert('After error, shows new digit', resultEl.textContent, '2');

    // Test 12: Negate
    calc.reset();
    btns[9].click(); // "7"
    btns[3].click(); // "±"
    assert('Negate 7', resultEl.textContent, '-7');

    // Test 13: Percent
    calc.reset();
    btns[10].click(); btns[11].click(); // "50"
    btns[4].click(); // "%"
    assert('50%', resultEl.textContent, '0.5');

    // Test 14: Chained operations 2+3+5=10
    calc.reset();
    btns[10].click(); // "2"
    btns[15].click(); // "+"
    btns[11].click(); // "3"
    btns[15].click(); // "+"
    btns[12].click(); // "5"
    btns[18].click(); // "="
    assert('2+3+5=10', resultEl.textContent.replace(/,/g, ''), '10');

    // Test 15: Keyboard support
    calc.reset();
    const keyDown = (key) => {
        const e = new KeyboardEvent('keydown', { key: key, bubbles: true, cancelable: true });
        document.dispatchEvent(e);
    };
    // Focus calculator window for keyboard handler
    WindowRegistry.focus('calculator');
    keyDown('7');
    keyDown('+');
    keyDown('3');
    keyDown('Enter');
    assert('Keyboard 7+3=10', resultEl.textContent.replace(/,/g, ''), '10');

    keyDown('Escape');
    assert('Keyboard Escape clears', resultEl.textContent.replace(/,/g, ''), '0');

    keyDown('5');
    keyDown('Backspace');
    assert('Backspace removes digit', resultEl.textContent.replace(/,/g, ''), '4');

    console.log('');
    console.log('===== SUMMARY =====');
    console.log(allPass ? 'ALL TESTS PASSED' : 'SOME TESTS FAILED');
    if (results.length > 0) {
        console.log('Failures:');
        results.forEach(r => console.log('  - ' + r));
    }
})();
