  calc.reset(); keyDown('6'); keyDown('*'); keyDown('4'); keyDown('='); assert('T16 6*4=24', resultEl.textContent.replace(/,/g,''), '24'); keyDown('Escape'); keyDown('1'); keyDown('0'); keyDown('0'); keyDown('/'); keyDown('2'); keyDown('Enter'); assert('T17 100/2=50', resultEl.textContent.replace(/,/g,''), '50');
  // T18: Backspace
  calc.reset(); keyDown('4'); keyDown('5'); keyDown('Backspace'); assert('T18 45->4', resultEl.textContent.replace(/,/g,''), '4');
  console.log(allPass ? 'ALL TESTS PASSED' : 'SOME TESTS FAILED');
  if (!allPass) console.log('Failures:', results);
  return { allPass: allPass, failures: results };
