.wallpaper-thumb.preview-2 { background: linear-gradient(135deg, #4facfe 0%, #00f2fe 100%); }
.wallpaper-thumb.preview-3 { background: linear-gradient(135deg, #43e97b 0%, #38f9d7 100%); }
.wallpaper-thumb.preview-4 { background: linear-gradient(135deg, #fa709a 0%, #fee140 100%); }
.wallpaper-thumb.preview-5 { background: linear-gradient(135deg, #a18cd1 0%, #fbc2eb 100%); }
.wallpaper-thumb.preview-6 { background-color: #1a1a2e; }
