  background-image:
    radial-gradient(ellipse at 20% 50%, rgba(72, 52, 212, 0.5) 0%, transparent 50%),
    radial-gradient(ellipse at 80% 50%, rgba(120, 40, 200, 0.4) 0%, transparent 50%);
