/* ===== Notepad ===== */
#notepad-window .window-body {
  display: flex;
  background: #ffffff;
  overflow: hidden;
}

.notepad-sidebar {
  width: 200px;
  min-width: 160px;
  background: #f9f9f9;
  border-right: 1px solid #e0e0e0;
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
}

.notepad-sidebar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 10px;
  border-bottom: 1px solid #e0e0e0;
  background: #f3f3f3;
}

.notepad-sidebar-header span {
  font-size: 12px;
  font-weight: 600;
  color: #333;
}

.notepad-sidebar-btn {
  width: 24px;
  height: 24px;
  border: none;
  background: transparent;
  border-radius: 4px;
  cursor: pointer;
  font-size: 16px;
  color: #555;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.1s, color 0.1s;
}

.notepad-sidebar-btn:hover {
  background: #e5e5e5;
  color: #333;
}

.notepad-document-list {
  flex: 1;
  overflow-y: auto;
  padding: 4px;
}

.notepad-document-item {
  padding: 8px 10px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 12px;
  color: #333;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  transition: background 0.1s;
  border: 1px solid transparent;
}

.notepad-document-item:hover {
  background: #f0f0f0;
}

.notepad-document-item.active {
  background: #e8f0fe;
  border-color: #0078d4;
  color: #1a1a1a;
}

.notepad-edit-area {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.notepad-toolbar {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 6px 10px;
  border-bottom: 1px solid #e0e0e0;
  background: #f3f3f3;
}

.notepad-toolbar-btn {
  padding: 5px 14px;
  border: 1px solid #d0d0d0;
  background: #ffffff;
  border-radius: 5px;
  cursor: pointer;
  font-size: 12px;
  font-family: inherit;
  color: #333;
  transition: background 0.1s, border-color 0.15s;
}

.notepad-toolbar-btn:hover {
  background: #f0f0f0;
  border-color: #c0c0c0;
}

.notepad-toolbar-btn:active {
  background: #e8e8e8;
}

.notepad-toolbar-btn.danger:hover {
  background: #fce4e4;
  border-color: #e53935;
  color: #e53935;
}

.notepad-textarea {
  flex: 1;
  border: none;
  outline: none;
  resize: none;
  padding: 12px;
  font-family: 'SF Mono', 'Menlo', 'Consolas', 'Courier New', monospace;
  font-size: 14px;
  line-height: 1.6;
  color: #1a1a1a;
  background: #ffffff;
  tab-size: 4;
}

.notepad-textarea::placeholder {
  color: #bbb;
}

/* ===== Scrollbar styling ===== */
::-webkit-scrollbar {

