/* ===== Desktop Icons ===== */
#desktop-icons {
  position: absolute;
  top: 16px;
  left: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  z-index: 1;
}

.desktop-icon {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 80px;
  padding: 8px 4px;
  border-radius: 8px;
  cursor: default;
  transition: background 0.15s;
}

.desktop-icon:hover {
  background: rgba(255, 255, 255, 0.15);
}

.desktop-icon:active {
  background: rgba(255, 255, 255, 0.25);
}

.desktop-icon-svg {
  width: 40px;
  height: 40px;
  margin-bottom: 4px;
  pointer-events: none;
}

.desktop-icon-label {
  color: white;
  font-size: 11px;
  text-align: center;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.6);
  line-height: 1.2;
  pointer-events: none;
  word-break: break-word;
}

/* ===== Windows ===== */
.window {
  position: absolute;
  min-width: 300px;
  min-height: 200px;
  border-radius: 10px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.25), 0 2px 8px rgba(0, 0, 0, 0.1);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transition: box-shadow 0.2s;
}

.window.focused {
  box-shadow: 0 12px 48px rgba(0, 0, 0, 0.3), 0 4px 12px rgba(0, 0, 0, 0.15);
}

.window:not(.focused) {
  opacity: 0.95;
}

/* Title bar */
.window-titlebar {
  display: flex;
  align-items: center;
  height: 36px;
  padding: 0 8px;
  background: #f3f3f3;
  border-bottom: 1px solid #e0e0e0;
  flex-shrink: 0;
  cursor: default;
}

.window.focused .window-titlebar {
  background: #ffffff;
  border-bottom-color: #d0d0d0;
}

.window-titlebar-text {
  flex: 1;
  font-size: 12px;
  font-weight: 500;
  color: #333;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  pointer-events: none;
}

.window-close-btn {
  width: 28px;
  height: 28px;
  border: none;
  background: transparent;
  border-radius: 6px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #666;
  font-size: 16px;
  transition: background 0.15s, color 0.15s;
}

.window-close-btn:hover {
  background: #e8e8e8;
  color: #333;
}

.window.focused .window-close-btn:hover {
  background: #e53935;
  color: white;
}

/* Window body */
.window-body {
  flex: 1;
  overflow: auto;
  background: #ffffff;
  position: relative;
}

