/* ===== Minesweeper ===== */
#minesweeper-window .window-body {
  display: flex;
  flex-direction: column;
  background: #f0f0f0;
  overflow: hidden;
  align-items: center;
}

.minesweeper-difficulty-bar {
  display: flex;
  gap: 4px;
  padding: 8px;
  background: #f3f3f3;
  border-bottom: 1px solid #e0e0e0;
  width: 100%;
  justify-content: center;
}

.minesweeper-difficulty-btn {
  padding: 5px 14px;
  border: 1px solid #d0d0d0;
  background: #ffffff;
  border-radius: 5px;
  cursor: pointer;
  font-size: 12px;
  font-family: inherit;
  color: #333;
  transition: background 0.1s, border-color 0.15s;
}

.minesweeper-difficulty-btn:hover {
  background: #f0f0f0;
  border-color: #c0c0c0;
}

.minesweeper-difficulty-btn.active {
  background: #0078d4;
  color: white;
  border-color: #0078d4;
}

.minesweeper-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 6px 10px;
  background: #e8e8e8;
  border-bottom: 1px solid #d0d0d0;
  border-top: 1px solid #e0e0e0;
}

.minesweeper-counter {
  font-family: 'SF Mono', 'Menlo', 'Consolas', 'Courier New', monospace;
  font-size: 22px;
  font-weight: bold;
  color: #e53935;
  background: #1a1a1a;
  padding: 2px 8px;
  border-radius: 4px;
  min-width: 60px;
  text-align: center;
  letter-spacing: 2px;
}

.minesweeper-face-btn {
  width: 36px;
  height: 36px;
  border: 1px solid #c0c0c0;
  background: #e8e8e8;
  border-radius: 6px;
  cursor: pointer;
  font-size: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.1s;
}

.minesweeper-face-btn:hover {
  background: #d8d8d8;
}

.minesweeper-face-btn:active {
  background: #c8c8c8;
}

.minesweeper-timer {
  font-family: 'SF Mono', 'Menlo', 'Consolas', 'Courier New', monospace;
  font-size: 22px;
  font-weight: bold;
  color: #0078d4;
  background: #1a1a1a;
  padding: 2px 8px;
  border-radius: 4px;
  min-width: 60px;
  text-align: center;
  letter-spacing: 2px;
}

.minesweeper-board {
  display: inline-flex;
  flex-direction: column;
  background: #d0d0d0;
  border: 2px solid #b0b0b0;
  margin: 4px;
}

.minesweeper-row {
  display: flex;
}

.minesweeper-cell {
  width: 28px;
  height: 28px;
  border: 1px solid #b8b8b8;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: bold;
  cursor: pointer;
  transition: background 0.05s;
  user-select: none;
  -webkit-user-select: none;
  background: linear-gradient(145deg, #e0e0e0, #c8c8c8);
}

.minesweeper-cell:hover:not(.revealed):not(.flagged-cell) {
  background: linear-gradient(145deg, #d8d8d8, #c0c0c0);
}

.minesweeper-cell.revealed {
  background: #e8e8e8;
  border-color: #d8d8d8;
  cursor: default;
}

.minesweeper-cell.flagged-cell {
  background: linear-gradient(145deg, #e0e0e0, #c8c8c8);
}

.minesweeper-cell.mine-revealed {
  background: #e53935;
}

.minesweeper-cell.mine-revealed-wrong {
  background: #ffe0b2;
}

.minesweeper-cell[data-number='1'] { color: #1976d2; }
.minesweeper-cell[data-number='2'] { color: #388e3c; }
.minesweeper-cell[data-number='3'] { color: #d32f2f; }
.minesweeper-cell[data-number='4'] { color: #7b1fa2; }
.minesweeper-cell[data-number='5'] { color: #ff8f00; }
.minesweeper-cell[data-number='6'] { color: #00897b; }
.minesweeper-cell[data-number='7'] { color: #424242; }
.minesweeper-cell[data-number='8'] { color: #757575; }

