  temp.style.cssText = 'position:fixed;top:50px;left:50px;width:400px;height:500px;background:white;z-index:9999';
  document.body.appendChild(temp);
  mw.currentDifficulty = 'beginner';
  mw.init(temp);
  const results = [];

  // Full suite
  mw._restart();
  results.push(mw.gameOver === false ? 'T1_pass' : 'T1_fail');
  results.push(mw.rows === 9 && mw.cols === 9 && mw.totalMines === 10 ? 'T2_pass' : 'T2_fail');
  mw._handleLeftClick(4, 4);
  let safeZoneOk = true;
  for (let dr = -1; dr <= 1; dr++) for (let dc = -1; dc <= 1; dc++) {
    const nr = 4+dr, nc = 4+dc;
    if (nr>=0 && nr<9 && nc>=0 && nc<9 && mw.board[nr][nc].mine) safeZoneOk = false;
  }
  results.push(safeZoneOk ? 'T3_pass' : 'T3_fail');
  results.push(mw.board[4][4].mine === false ? 'T4_pass' : 'T4_fail');
  results.push(mw.board[4][4].revealed === true ? 'T5_pass' : 'T5_fail');
  mw._restart();
  mw._handleRightClick(0, 0);
  results.push(mw.flagsPlaced === 1 && mw.board[0][0].flagged ? 'T6_pass' : 'T6_fail');
  mw.flagsPlaced = 12; mw._updateCounter();
  results.push(mw.counterEl.textContent === '-02' ? 'T7_pass' : 'T7_fail: ' + mw.counterEl.textContent);
  mw.currentDifficulty = 'intermediate'; mw._restart();
  results.push(mw.rows===16 && mw.cols===16 && mw.totalMines===40 ? 'T8_pass' : 'T8_fail');
  mw.currentDifficulty = 'expert'; mw._restart();
  results.push(mw.rows===16 && mw.cols===30 && mw.totalMines===99 ? 'T9_pass' : 'T9_fail');
  mw.currentDifficulty = 'beginner'; mw._restart();
  mw._handleLeftClick(4, 4); mw._stopTimer();
  results.push(mw.timerInterval === null ? 'T10_pass' : 'T10_fail');
  mw.timerValue = 999; mw._updateTimer();
  results.push(mw.timerEl.textContent === '999' ? 'T11_pass' : 'T11_fail');
  mw._restart();
  for (let r=0;r<9;r++) for(let c=0;c<9;c++) mw.board[r][c].mine = false;
  mw.totalMines = 0;
  for (let r=0;r<9;r++) for(let c=0;c<9;c++) mw._revealCell(r,c);
  mw._checkWin();
  results.push(mw.gameWon === true ? 'T12_pass' : 'T12_fail');
  results.push(mw.faceBtn.textContent === '😎' ? 'T13_pass' : 'T13_fail');
  // Lose test
  mw._restart();
  mw._handleLeftClick(4, 4); mw._stopTimer();
  let mineR=-1, mineC=-1;
  for(let r=0;r<9;r++) for(let c=0;c<9;c++) if(mw.board[r][c].mine && !(r===4&&c===4)) { mineR=r; mineC=c; break; }
  if (mineR >= 0) {
    mw._handleLeftClick(mineR, mineC);
    results.push(mw.gameOver === true ? 'T14_pass' : 'T14_fail');
    results.push(mw.board[mineR][mineC].revealed === true ? 'T15_pass' : 'T15_fail');
    results.push(mw.faceBtn.textContent === '😵' ? 'T16_pass' : 'T16_fail');
  }
  return results.join(', ');
}" 2>&1

