/* ===== Reset & Base ===== */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  font-size: 13px;
  color: #1a1a1a;
  user-select: none;
  -webkit-user-select: none;
}

/* ===== Desktop ===== */
#desktop {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 48px;
  overflow: hidden;
  /* Default wallpaper: a nice gradient */
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
}

/* Wallpaper presets */
#desktop.wallpaper-0 { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); }
#desktop.wallpaper-1 { background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%); }
#desktop.wallpaper-2 { background: linear-gradient(135deg, #4facfe 0%, #00f2fe 100%); }
#desktop.wallpaper-3 { background: linear-gradient(135deg, #43e97b 0%, #38f9d7 100%); }
#desktop.wallpaper-4 { background: linear-gradient(135deg, #fa709a 0%, #fee140 100%); }
#desktop.wallpaper-5 { background: linear-gradient(135deg, #a18cd1 0%, #fbc2eb 100%); }
#desktop.wallpaper-6 { background-color: #1a1a2e; }
#desktop.wallpaper-7 {
  background-color: #0f0f23;
  background-image:
    radial-gradient(ellipse at 20% 50%, rgba(72, 52, 212, 0.3) 0%, transparent 50%),
    radial-gradient(ellipse at 80% 50%, rgba(120, 40, 200, 0.2) 0%, transparent 50%);
}

/* ===== Desktop Icons ===== */
#desktop-icons {
  position: absolute;
  top: 16px;
  left: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  z-index: 1;
}

.desktop-icon {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 80px;
  padding: 8px 4px;
  border-radius: 8px;
  cursor: default;
  transition: background 0.15s;
}

.desktop-icon:hover {
  background: rgba(255, 255, 255, 0.15);
}

.desktop-icon:active {
  background: rgba(255, 255, 255, 0.25);
}

.desktop-icon-svg {
  width: 40px;
  height: 40px;
  margin-bottom: 4px;
  pointer-events: none;
}

.desktop-icon-label {
  color: white;
  font-size: 11px;
  text-align: center;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.6);
  line-height: 1.2;
  pointer-events: none;
  word-break: break-word;
}

/* ===== Windows ===== */
.window {
  position: absolute;
  min-width: 300px;
  min-height: 200px;
  border-radius: 10px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.25), 0 2px 8px rgba(0, 0, 0, 0.1);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transition: box-shadow 0.2s;
}

.window.focused {
  box-shadow: 0 12px 48px rgba(0, 0, 0, 0.3), 0 4px 12px rgba(0, 0, 0, 0.15);
}

.window:not(.focused) {
  opacity: 0.95;
}

/* Title bar */
.window-titlebar {
  display: flex;
  align-items: center;
  height: 36px;
  padding: 0 8px;
  background: #f3f3f3;
  border-bottom: 1px solid #e0e0e0;
  flex-shrink: 0;
  cursor: default;
}

.window.focused .window-titlebar {
  background: #ffffff;
  border-bottom-color: #d0d0d0;
}

.window-titlebar-text {
  flex: 1;
  font-size: 12px;
  font-weight: 500;
  color: #333;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  pointer-events: none;
}

.window-close-btn {
  width: 28px;
  height: 28px;
  border: none;
  background: transparent;
  border-radius: 6px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #666;
