}

/* ===== Wallpaper Picker ===== */
.wallpaper-picker {
  padding: 8px;
  min-width: 280px;
}

.wallpaper-picker-header {
  font-size: 12px;
  font-weight: 600;
  color: #333;
  padding: 4px 8px 8px;
  border-bottom: 1px solid rgba(0, 0, 0, 0.06);
  margin-bottom: 8px;
}

.wallpaper-picker-grid {
