/* Wallpaper thumb CSS-only previews */
.wallpaper-thumb.preview-0 { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); }
.wallpaper-thumb.preview-1 { background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%); }
