/* ===== Taskbar ===== */
#taskbar {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  height: 48px;
  background: rgba(243, 243, 243, 0.85);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-top: 1px solid rgba(0, 0, 0, 0.08);
  display: flex;
  align-items: center;
  padding: 0 8px;
  z-index: 10000;
}

#taskbar-buttons {
  flex: 1;
  display: flex;
  gap: 4px;
  overflow-x: auto;
  align-items: center;
}

.taskbar-button {
  height: 36px;
  padding: 0 14px;
  border: none;
  background: transparent;
  border-radius: 6px;
  cursor: pointer;
  font-size: 12px;
  font-family: inherit;
  color: #333;
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: background 0.15s;
  position: relative;
}

.taskbar-button:hover {
  background: rgba(0, 0, 0, 0.06);
}

.taskbar-button.active {
  background: rgba(0, 0, 0, 0.1);
}

.taskbar-button.active::after {
  content: '';
  position: absolute;
  bottom: 2px;
  left: 50%;
  transform: translateX(-50%);
  width: 18px;
  height: 3px;
  border-radius: 2px;
  background: #0078d4;
}

.taskbar-clock {
  padding: 0 12px;
  font-size: 12px;
  color: #333;
  white-space: nowrap;
  min-width: 60px;
  text-align: right;
}

